window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["cnn"]={"title":"卷积神经网络 CNN：让同一个局部检测器扫遍空间","subtitle":"从离散卷积、权重共享和输出形状，到感受野、采样混叠、平移等变与现代视觉骨干。","thesis":"CNN 用局部连接和权重共享把同一模式检测器应用于所有位置，以较少参数建立平移等变归纳偏置。多层堆叠把边缘组合成纹理、部件和对象；但<b>下采样会丢位置与高频，全局关系需要深层、空洞、注意力或多尺度路径</b>。","quality":{"contractVersion":2,"examples":[{"section":2,"evidence":{"setup":"四个窗口","rule":"局部内积","steps":"3−0=3","interpretation":"正负号表示两条对角位置的相对亮度"}}],"termReviews":[{"section":8,"reviewedAt":"2026-07-26","terms":[{"name":"归纳偏置","meaning":"模型结构预先偏向某类规律的假设","purpose":"说明普通卷积天然偏好平移等变而非所有变换不变","definitionEvidence":"归纳偏置","purposeEvidence":"平移等变"}]}],"formulas":[{"id":"cnn-shared-convolution","section":1,"formulaIndex":1,"symbols":[{"name":"Y","meaning":"卷积计算得到的输出特征图","evidence":"Y 是输出特征图"},{"name":"i","meaning":"输出特征图的纵向空间位置","evidence":"i、j 是输出空间位置"},{"name":"j","meaning":"输出特征图的横向空间位置","evidence":"i、j 是输出空间位置"},{"name":"o","meaning":"被计算的输出通道编号","evidence":"o 是输出通道"},{"name":"u","meaning":"核窗口内纵向位置","evidence":"u、v 是核窗口内位置"},{"name":"v","meaning":"核窗口内横向位置","evidence":"u、v 是核窗口内位置"},{"name":"c","meaning":"参与求和的输入通道编号","evidence":"c 是输入通道"},{"name":"K","meaning":"在所有空间位置复用的卷积核权重","evidence":"K 是共享核权重"},{"name":"X","meaning":"输入到卷积的特征图","evidence":"X 是输入特征图"},{"name":"b","meaning":"每个输出通道使用的偏置","evidence":"b[o] 是输出通道偏置"}]},{"id":"cnn-worked-feature-map","section":2,"formulaIndex":1,"symbols":[{"name":"Y","meaning":"四个局部窗口内积组成的二乘二特征图","evidence":"四个窗口得到一张 2×2 特征图"}]},{"id":"cnn-output-shape","section":3,"formulaIndex":1,"symbols":[{"name":"out","meaning":"单个空间轴的输出长度","evidence":"out 是输出长度"},{"name":"in","meaning":"单个空间轴的输入长度","evidence":"in 是单个空间轴的输入长度"},{"name":"p","meaning":"输入两侧的填充量","evidence":"p 是两侧填充量"},{"name":"d","meaning":"核元素间隔使用的膨胀率","evidence":"d 是膨胀率"},{"name":"k","meaning":"卷积核在该轴上的宽度","evidence":"k 是核宽度"},{"name":"s","meaning":"窗口每次移动的步幅","evidence":"s 是步幅"}]},{"id":"cnn-parameter-count","section":4,"formulaIndex":1,"symbols":[{"name":"k","meaning":"卷积核的高或宽","evidence":"kₕ、k𝓌 是核的高和宽"},{"name":"C","meaning":"卷积的输入或输出通道数量","evidence":"Cᵢₙ 是输入通道数"}]},{"id":"cnn-receptive-field","section":6,"formulaIndex":1,"symbols":[{"name":"r","meaning":"当前层单元映回原输入的理论感受野边长","evidence":"rₗ 是该层单元在原输入上的理论感受野边长"},{"name":"k","meaning":"当前层卷积核宽度","evidence":"kₗ 是核宽"},{"name":"j","meaning":"当前层相邻单元中心映回输入的跳距","evidence":"jₗ 是相邻单元中心映回输入时的跳距"},{"name":"s","meaning":"当前层卷积步幅","evidence":"sₗ 是步幅"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"卷积是在滑动局部窗口上重复使用同一核权重的多通道内积。","evidence":"卷积是滑动窗口上的共享内积"},"problem":{"answer":"它用较少参数在任意空间位置检测同一局部模式。","evidence":"为什么一套边缘核能在图片任意位置工作"},"inputOutput":{"answer":"输入特征图 X 和核 K，输出按位置与通道组织的特征图 Y。","evidence":"X 是输入特征图"},"mechanism":{"answer":"取局部窗口逐项乘核并跨位置和输入通道求和，再加偏置。","evidence":"跨窗口和输入通道相加"},"interpretation":{"answer":"响应正负只表示当前核方向和强度，不等于检测到可命名对象。","evidence":"不自动等于某个可命名对象"},"boundary":{"answer":"许多库实现互相关而不翻核，边界、步幅和缩放也会破坏理想性质。","evidence":"实现互相关而不翻转核"}},{"section":2,"definition":{"answer":"该例用一个二乘二核遍历三乘三灰度图并得到四个响应。","evidence":"四个窗口得到一张 2×2 特征图"},"problem":{"answer":"它展示每个特征图元素如何由对应局部窗口内积得到。","evidence":"局部内积怎样响应"},"inputOutput":{"answer":"输入给定 X、K、步幅一和无填充，输出 Y=[[-2,1],[-1,3]]。","evidence":"Y=[[1−3, 2−1],[0−1, 3−0]]"},"mechanism":{"answer":"按四个窗口左上角切片，与核逐项相乘并相加。","evidence":"左上到右下的亮度差"},"interpretation":{"answer":"正负响应表示两条对角位置的相对亮度，而非对象身份。","evidence":"而非“发现了对象”"},"boundary":{"answer":"一个手工核只响应一种局部差异，真实网络需学习多核并非线性组合。","evidence":"训练会从任务损失中学习许多核"}},{"section":3,"definition":{"answer":"输出几何由输入长度、核、填充、步幅和膨胀共同决定。","evidence":"步幅、填充和膨胀决定输出几何"},"problem":{"answer":"它防止尺寸计算错误导致残差无法相加或特征错位。","evidence":"尺寸错一格为何会让残差相加失败"},"inputOutput":{"answer":"输入 in、k、p、s、d，输出向下取整的空间长度 out。","evidence":"out 是输出长度"},"mechanism":{"answer":"先算膨胀核有效覆盖，从填充后长度扣除，再按步幅计窗口数。","evidence":"只保留完整落入规则的窗口"},"interpretation":{"answer":"示例 32 输入在 k3、p1、s2 下输出 16。","evidence":"out=⌊(32+2−2−1)/2⌋+1=16"},"boundary":{"answer":"偶数核或大步幅时框架左右填充规则可能不同。","evidence":"不同框架的左右填充规则可能不同"}},{"section":4,"definition":{"answer":"卷积参数量由核面积和输入输出通道决定，而不由图像面积决定。","evidence":"通道决定参数量，不由图片面积决定"},"problem":{"answer":"它估算模型容量并区分参数存储与空间计算成本。","evidence":"3×3 卷积从64通道变128通道有多少参数"},"inputOutput":{"answer":"输入核高宽、Cin、Cout 与偏置约定，输出总参数量。","evidence":"每个输出通道还有一个偏置"},"mechanism":{"answer":"每个输出通道持有 kh×kw×Cin 个权重和一个偏置。","evidence":"括号内加 1"},"interpretation":{"answer":"示例共有 73,856 参数，在所有空间位置共享。","evidence":"空间位置共享这 73,856 个参数"},"boundary":{"answer":"参数量不随面积变，但乘加计算仍随输出空间面积增长。","evidence":"乘加计算量会随输出空间面积增长"}},{"section":5,"definition":{"answer":"平移等变表示输入移动时卷积特征响应按同样位移移动。","evidence":"共享核产生平移等变响应"},"problem":{"answer":"它解释共享核为何能在不同空间位置检测同一模式。","evidence":"输入向右移动一格"},"inputOutput":{"answer":"输入图像及其平移版本，输出对应平移的卷积特征图。","evidence":"响应也右移 1 格"},"mechanism":{"answer":"同一 K 在全部位置使用，因此相同局部图案产生相同响应。","evidence":"所有位置同一 K"},"interpretation":{"answer":"等变保留位置变化；分类不变还需池化、增强或聚合。","evidence":"分类不变还需全局池化"},"boundary":{"answer":"边界填充和离散采样会破坏严格平移等变。","evidence":"忽略边界与采样"}},{"section":6,"definition":{"answer":"感受野是某层单元理论上能受原输入多大区域影响。","evidence":"感受野按跳距逐层增长"},"problem":{"answer":"它判断局部卷积堆叠何时能够汇集更大范围上下文。","evidence":"能看多大区域"},"inputOutput":{"answer":"输入各层核与步幅，输出逐层跳距 j 和感受野 r。","evidence":"从 r₀=1、j₀=1 开始"},"mechanism":{"answer":"当前核新增 k−1 个前层跳距覆盖，并把跳距乘步幅。","evidence":"后续每增加一个核位置会跨更大输入距离"},"interpretation":{"answer":"三层三乘三步幅一的理论感受野为七乘七。","evidence":"理论感受野为 7×7"},"boundary":{"answer":"理论覆盖不等于有效贡献，真实梯度影响常集中在中心。","evidence":"理论覆盖不等于有效贡献"}},{"section":7,"definition":{"answer":"混叠是降采样前高频未滤除而折叠成低频伪影。","evidence":"下采样前不过滤会产生混叠"},"problem":{"answer":"它解释棋盘纹理缩小后为何出现原图不存在的结构。","evidence":"变成不存在的图案"},"inputOutput":{"answer":"输入高分辨率特征和降采样算子，输出较小特征图及潜在伪影。","evidence":"stride卷积或池化减少采样率"},"mechanism":{"answer":"超过新奈奎斯特频率的细节折叠到低频，低通可先抑制。","evidence":"折叠为低频伪影"},"interpretation":{"answer":"伪纹理或小目标消失提示采样信息损失，不只是压缩。","evidence":"小物体若小于一个下采样单元"},"boundary":{"answer":"平均或低通能减轻混叠但也可能损伤任务需要的高频细节。","evidence":"不是免费压缩"}},{"section":8,"definition":{"answer":"等变让输出随变换移动，不变让输出在变换后保持相同。","evidence":"等变、不变与数据增强不能混为一谈"},"problem":{"answer":"它澄清普通 CNN 是否天然忽略平移、旋转和尺度变化。","evidence":"是否天生对旋转、缩放都不敏感"},"inputOutput":{"answer":"输入变换前后图像，输出随动特征或保持不变的任务预测。","evidence":"输入移动，特征同样移动"},"mechanism":{"answer":"卷积近似平移等变；池化与训练形成不变，增强注入额外假设。","evidence":"需聚合与训练"},"interpretation":{"answer":"增强等于声明哪些变化不应改变标签，须符合任务语义。","evidence":"告诉模型哪些变换应保持标签"},"boundary":{"answer":"错误增强会注入错误不变性，例如旋转数字六仍强制同标签。","evidence":"增强反而注入错误不变性"}},{"section":9,"definition":{"answer":"CNN、ViT 与混合骨干是不同局部和全局关系建模方案。","evidence":"各有计算甜点区"},"problem":{"answer":"它根据数据、延迟、任务尺度和全局关系需求选择视觉骨干。","evidence":"注意力出现后为什么卷积仍广泛存在"},"inputOutput":{"answer":"输入任务和资源约束，输出需实测的 CNN、ViT 或混合候选。","evidence":"约束 优先验证"},"mechanism":{"answer":"CNN 依赖局部共享和金字塔，ViT 用注意力直接连接全局内容。","evidence":"ViT 更直接建立全局内容关系"},"interpretation":{"answer":"有限数据端侧和密集预测常利于 CNN，大规模全局任务可利于 ViT。","evidence":"有限数据、端侧和密集预测中高效"},"boundary":{"answer":"两类架构不断互借，最终选择须在目标硬件和数据上验证。","evidence":"两类设计不断互借"}},{"section":11,"definition":{"answer":"特征可视化展示某通道与输入区域的相关响应，不是因果解释。","evidence":"可视化特征不能替代干预验证"},"problem":{"answer":"它防止看到高激活样本后直接给通道命名为对象检测器。","evidence":"就能把它命名为轮子检测器吗"},"inputOutput":{"answer":"输入通道与样本，输出激活图及遮挡、替换、消融的变化证据。","evidence":"最大激活样本只展示相关性"},"mechanism":{"answer":"用遮挡、反事实和消融主动改变候选特征，再比较输出。","evidence":"配合遮挡、反事实替换、特征消融"},"interpretation":{"answer":"跨数据集干预都稳定改变输出才支持模型确实依赖该特征。","evidence":"观察干预是否稳定改变输出"},"boundary":{"answer":"单张显著图不能证明依赖区域，更不能证明因果机制。","evidence":"更不能证明因果机制"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算一次二维卷积；计算输出尺寸和参数量；区分等变与不变；推导感受野并识别下采样混叠。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>卷积是滑动窗口上的共享内积<span class=\"dd-badge math\">核心机制</span></h2><p class=\"dd-lead\">为什么一套边缘核能在图片任意位置工作？</p><div class=\"dd-formula\">Y[i,j,o]=Σ<sub>u,v,c</sub>K[u,v,c,o]X[i+u,j+v,c]+b[o]</div><p><code>X</code> 是输入特征图，<code>Y</code> 是输出特征图；<code>i、j</code> 是输出空间位置，<code>o</code> 是输出通道；<code>u、v</code> 是核窗口内位置，<code>c</code> 是输入通道；<code>K</code> 是共享核权重，<code>b[o]</code> 是输出通道偏置。求和表示取当前位置的局部窗口，与核逐项相乘后跨窗口和输入通道相加。</p><p>核 K 在空间各位置复用，只随输入/输出通道变化。局部连接减少计算，权重共享让同一模式移动时响应也随之移动。输出正负只表示当前核的响应方向和强度，不自动等于某个可命名对象。深度学习库常实现互相关而不翻转核，但通常仍称卷积。</p><div class=\"dd-note\"><b>贯穿例子：</b>用 2×2 核 K=[[1,0],[0,−1]] 扫描 3×3 灰度图 X=[[1,2,0],[0,3,1],[2,1,0]]，步幅1、无填充。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四个窗口得到一张 2×2 特征图<span class=\"dd-badge math\">手算</span></h2><p class=\"dd-lead\">局部内积怎样响应左上到右下的亮度差？</p><div class=\"dd-formula\">Y=[[1−3, 2−1],[0−1, 3−0]]=[[-2,1],[-1,3]]</div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>窗口左上角</th><th>窗口</th><th>内积</th></tr></thead><tbody><tr><td>(0,0)</td><td>[[1,2],[0,3]]</td><td>1−3=−2</td></tr><tr><td>(0,1)</td><td>[[2,0],[3,1]]</td><td>2−1=1</td></tr><tr><td>(1,0)</td><td>[[0,3],[2,1]]</td><td>0−1=−1</td></tr><tr><td>(1,1)</td><td>[[3,1],[1,0]]</td><td>3−0=3</td></tr></tbody></table></div><p>正负号表示两条对角位置的相对亮度，而非“发现了对象”。训练会从任务损失中学习许多核，再经非线性组合。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>步幅、填充和膨胀决定输出几何<span class=\"dd-badge math\">形状</span></h2><p class=\"dd-lead\">尺寸错一格为何会让残差相加失败？</p><div class=\"dd-formula\">out=⌊(in+2p−d(k−1)−1)/s⌋+1</div><p><code>in</code> 是单个空间轴的输入长度，<code>out</code> 是输出长度，<code>k</code> 是核宽度，<code>p</code> 是两侧填充量，<code>s</code> 是步幅，<code>d</code> 是膨胀率，向下取整表示只保留完整落入规则的窗口。对 32×32 输入、k=3、p=1、s=2、d=1，out=⌊(32+2−2−1)/2⌋+1=16。same padding 通常让 s=1 时尺寸不变；偶数核或 s&gt;1 时不同框架的左右填充规则可能不同。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>参数</th><th>主要作用</th><th>常见风险</th></tr></thead><tbody><tr><td>padding p</td><td>保留边缘/尺寸</td><td>引入人工边界</td></tr><tr><td>stride s</td><td>下采样</td><td>混叠、小目标丢失</td></tr><tr><td>dilation d</td><td>扩大覆盖</td><td>栅格效应</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>通道决定参数量，不由图片面积决定<span class=\"dd-badge math\">参数</span></h2><p class=\"dd-lead\">3×3 卷积从64通道变128通道有多少参数？</p><div class=\"dd-formula\">参数=(kₕk𝓌Cᵢₙ+1)Cₒᵤₜ=(3×3×64+1)×128=73,856</div><p><code>kₕ、k𝓌</code> 是核的高和宽，<code>Cᵢₙ</code> 是输入通道数，<code>Cₒᵤₜ</code> 是输出通道数；每个输出通道还有一个偏置，所以括号内加 1。空间位置共享这 73,856 个参数，无论特征图是 16×16 还是 256×256。参数量不随图片面积变，但乘加计算量会随输出空间面积增长。</p><p>1×1 卷积不混合邻居，只在每个位置混合通道；depthwise 卷积每通道单独做空间核，再用 pointwise 混合通道，显著降低计算，但通道交互和硬件效率仍须实测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：共享核产生平移等变响应<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">输入向右移动一格，特征为何也应向右移动？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 300\" role=\"img\" aria-label=\"共享卷积核扫描移动图案并产生移动响应\"><defs><marker id=\"cnna\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><text x=\"100\" y=\"35\" class=\"svg-t\">输入 A</text><g fill=\"#252a33\" stroke=\"#596273\"><rect x=\"45\" y=\"55\" width=\"45\" height=\"45\"/><rect x=\"90\" y=\"55\" width=\"45\" height=\"45\" fill=\"#d3a05a\"/><rect x=\"135\" y=\"55\" width=\"45\" height=\"45\"/><rect x=\"45\" y=\"100\" width=\"45\" height=\"45\"/><rect x=\"90\" y=\"100\" width=\"45\" height=\"45\" fill=\"#d3a05a\"/><rect x=\"135\" y=\"100\" width=\"45\" height=\"45\"/></g><path d=\"M195,100 L270,100\" stroke=\"#788293\" marker-end=\"url(#cnna)\"/><rect x=\"285\" y=\"70\" width=\"86\" height=\"62\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"328\" y=\"95\" text-anchor=\"middle\" class=\"svg-t\">共享竖边核</text><text x=\"328\" y=\"116\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">所有位置同一 K</text><path d=\"M371,100 L440,100\" stroke=\"#788293\" marker-end=\"url(#cnna)\"/><g fill=\"#252a33\" stroke=\"#596273\"><rect x=\"455\" y=\"55\" width=\"45\" height=\"45\"/><rect x=\"500\" y=\"55\" width=\"45\" height=\"45\" fill=\"#65a6d9\"/><rect x=\"545\" y=\"55\" width=\"45\" height=\"45\"/><rect x=\"455\" y=\"100\" width=\"45\" height=\"45\"/><rect x=\"500\" y=\"100\" width=\"45\" height=\"45\" fill=\"#65a6d9\"/><rect x=\"545\" y=\"100\" width=\"45\" height=\"45\"/></g><text x=\"500\" y=\"35\" class=\"svg-t\">响应 A</text><text x=\"90\" y=\"203\" class=\"svg-t\">输入右移 1 格</text><path d=\"M188,198 L440,198\" stroke=\"#788293\" marker-end=\"url(#cnna)\"/><text x=\"470\" y=\"203\" class=\"svg-t\">响应也右移 1 格</text><line x1=\"112\" y1=\"155\" x2=\"112\" y2=\"185\" stroke=\"#d3a05a\"/><line x1=\"522\" y1=\"155\" x2=\"522\" y2=\"185\" stroke=\"#65a6d9\"/><text x=\"365\" y=\"270\" text-anchor=\"middle\" class=\"svg-t\">F(TδX)=TδF(X)（忽略边界与采样）</text></svg><figcaption>图 1　平移等变意味着特征位置随输入一起移动；分类不变还需全局池化、增强或其他聚合。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>感受野按跳距逐层增长<span class=\"dd-badge math\">层级</span></h2><p class=\"dd-lead\">三层 3×3、stride=1 的单元能看多大区域？</p><div class=\"dd-formula\">rₗ=rₗ₋₁+(kₗ−1)jₗ₋₁，　jₗ=jₗ₋₁sₗ</div><p><code>l</code> 是层编号，<code>rₗ</code> 是该层单元在原输入上的理论感受野边长，<code>jₗ</code> 是相邻单元中心映回输入时的跳距，<code>kₗ</code> 是核宽，<code>sₗ</code> 是步幅。从 r₀=1、j₀=1 开始，三层 3×3、s=1 得 r=3、5、7，因此理论感受野为 7×7。若第二层 stride=2，则后续每增加一个核位置会跨更大输入距离。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层</th><th>k/s</th><th>跳距 j</th><th>感受野 r</th></tr></thead><tbody><tr><td>输入</td><td>—</td><td>1</td><td>1</td></tr><tr><td>conv1</td><td>3/1</td><td>1</td><td>3</td></tr><tr><td>conv2</td><td>3/1</td><td>1</td><td>5</td></tr><tr><td>conv3</td><td>3/1</td><td>1</td><td>7</td></tr></tbody></table></div><p>理论覆盖不等于有效贡献：梯度往往集中在中心。检测、分割需用多尺度特征连接高分辨率细节与深层语义。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>下采样前不过滤会产生混叠<span class=\"dd-badge eng\">采样边界</span></h2><p class=\"dd-lead\">棋盘纹理缩小后为何会变成不存在的图案？</p><p>stride卷积或池化减少采样率，超过新奈奎斯特频率的细节会折叠为低频伪影。最大池化带来局部稳定性，但可能保留噪声峰值；平均/低通后再降采样更抗混叠。小物体若小于一个下采样单元，可能完全消失。</p><div class=\"dd-note warn\"><b>更小特征图不是免费压缩。</b>必须按目标尺寸、旋转、缩放、边界位置和压缩噪声做切片测试。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>等变、不变与数据增强不能混为一谈<span class=\"dd-badge intuition\">归纳偏置</span></h2><p class=\"dd-lead\">CNN 是否天生对旋转、缩放都不敏感？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>性质</th><th>含义</th><th>普通卷积是否天然具备</th></tr></thead><tbody><tr><td>平移等变</td><td>输入移动，特征同样移动</td><td>近似；边界/stride会破坏</td></tr><tr><td>分类平移不变</td><td>移动后类别不变</td><td>需聚合与训练</td></tr><tr><td>旋转/尺度不变</td><td>变换后输出不变</td><td>否；需增强或专门结构</td></tr></tbody></table></div><p>增强相当于告诉模型哪些变换应保持标签。若对数字6做180°旋转仍强制同标签，增强反而注入错误不变性。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>CNN、ViT 与混合骨干各有计算甜点区<span class=\"dd-badge eng\">选型</span></h2><p class=\"dd-lead\">注意力出现后为什么卷积仍广泛存在？</p><p>CNN 的局部先验、成熟内核和多尺度金字塔在有限数据、端侧和密集预测中高效；ViT 更直接建立全局内容关系，规模化训练表现强，但注意力成本和数据需求更高。现代 ConvNeXt、混合注意力及视觉基础模型说明两类设计不断互借。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>约束</th><th>优先验证</th></tr></thead><tbody><tr><td>端侧低延迟</td><td>depthwise CNN、量化</td></tr><tr><td>小目标检测</td><td>高分辨率、多尺度 CNN/混合骨干</td></tr><tr><td>全局关系与大规模预训练</td><td>ViT/混合注意力</td></tr><tr><td>视频流</td><td>时空卷积与缓存策略</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">从卷积算术走向采样理论和任务头。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>卷积核就是可命名边缘</td><td>中高层通道通常是分布式组合</td></tr><tr><td>等变等于不变</td><td>等变输出随输入移动</td></tr><tr><td>same padding 没有副作用</td><td>边界由人工值影响</td></tr><tr><td>理论感受野就是实际使用范围</td><td>有效影响常集中中心</td></tr><tr><td>下采样只省计算</td><td>还会丢细节并产生混叠</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>神经网络、矩阵内积、图像采样</td></tr><tr><td><b>本页核心</b></td><td>共享核、形状、感受野、等变、混叠</td></tr><tr><td>架构</td><td>残差连接、归一化、ViT</td></tr><tr><td>任务</td><td>分类、检测、分割、超分辨率</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>可视化特征不能替代干预验证<span class=\"dd-badge eng\">解释边界</span></h2><p class=\"dd-lead\">看到某通道对“轮子”高激活，就能把它命名为轮子检测器吗？</p><p>最大激活样本只展示相关性，通道也可能响应纹理、背景或共现位置。应配合遮挡、反事实替换、特征消融和跨数据集复现，观察干预是否稳定改变输出。单张显著图漂亮，不代表网络真正依赖该区域，更不能证明因果机制。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>局部窗口进入共享卷积核</li><li>通道内积产生特征图</li><li>非线性堆叠扩大感受野</li><li>下采样形成多尺度层级</li><li>任务头聚合或恢复空间输出</li><li>以变换、尺度和边界切片验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>贯穿例子的右下输出为何是3？</li><li>32输入、k3、p1、s2的输出是多少？</li><li>3×3、64到128通道含偏置参数量？</li><li>三层3×3、stride1的感受野？</li><li>平移等变为何不等于分类不变？</li><li>假设“卷积神经网络 CNN：让同一个局部检测器扫遍空间”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“卷积神经网络 CNN：让同一个局部检测器扫遍空间”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“卷积神经网络 CNN：让同一个局部检测器扫遍空间”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>窗口[[3,1],[1,0]]与核内积为3×1+0×(−1)=3。</li><li>16。</li><li>(3×3×64+1)×128=73,856。</li><li>7×7。</li><li>等变特征随输入移动；需池化等聚合才可能让类别保持不变。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1603.07285\" target=\"_blank\" rel=\"noopener\">A Guide to Convolution Arithmetic for Deep Learning</a>：卷积形状计算</li><li><a href=\"https://proceedings.neurips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks.pdf\" target=\"_blank\" rel=\"noopener\">ImageNet Classification with Deep Convolutional Neural Networks</a>：AlexNet</li><li><a href=\"https://arxiv.org/abs/1512.03385\" target=\"_blank\" rel=\"noopener\">Deep Residual Learning for Image Recognition</a>：残差 CNN</li><li><a href=\"https://arxiv.org/abs/1904.11486\" target=\"_blank\" rel=\"noopener\">Making Convolutional Networks Shift-Invariant Again</a>：下采样与抗混叠</li><li><a href=\"https://arxiv.org/abs/2010.11929\" target=\"_blank\" rel=\"noopener\">An Image is Worth 16x16 Words</a>：Vision Transformer 对照</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
